repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('upper', 47), ('upper', 16), ('hill', 19), ('lower', 40), ('lower', 18), ('lower', 51)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.catalog.py:
"""Registry of harvests by field."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered harvest."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(harvest):
    """Add one harvest to the registry."""
    _ALL.append(harvest)


def find(field):
    """Return the harvests registered under this field."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.field, []).append(x)
    return _BY_KEY.get(field, [])
